INSERT IGNORE INTO books (title, author, publisher, isbn, category_id, location, price, publish_date, cover_url, description, total_count, available_count, status, create_time) VALUES
  ('平凡的世界（激励亿万读者的新课标经典、改变马云一生的书、新晋男神朱一龙推荐）', '路遥', '北京十月文艺出版社', '9787530212004', 113, 'A区4排6架', 86.37, '2017-05', '/api/uploads/covers/199296.jpg', '《平凡的世界》是中国作家路遥创作的一部百万字的小说。这是一部全景式地表现中国当代城乡社会生活的长篇小说，全书共三部。 该书以中国70年代中期到80年代中期十年间为背景，通过复杂的矛盾纠葛，以孙少安和孙少平两兄弟为中心，刻画了当时社会各阶层众多普通人的形象；劳动与爱情、挫折与追求、痛苦与欢乐、日常生活与巨大社会冲突纷繁地交织在一起，深刻地展示了普通人在大时代历史进程中所走过的艰难曲折的道路。', 2, 2, 1, '2026-09-09 19:07:07'),
  ('《少年阿宾》（全本+外篇）', '2016-11', '', '9000000133705', 113, 'C区12排12架', 39.25, '2016-11', '/api/uploads/covers/133705.jpg', '《少年阿宾》是一部描写青少年成长的小说，通过主人公阿宾的视角，展现了他在家庭、学校和社会的多重压力下的成长历程。小说不仅描绘了阿宾与家人的关系，还深入探讨了青少年在青春期所面临的困惑和挑战。外篇部分则进一步扩展了故事背景，增加了更多角色和情节，使整个故事更加丰满。 这部作品以其真实的情感和细腻的笔触，赢得了广大读者的喜爱，尤其是青少年读者群体。它不仅是一部文学作品，更是一面镜子，反映了当代青少年的生活和心理状态。', 7, 7, 1, '2026-09-09 19:07:07'),
  ('小王子（作家榜经典 2017未删节新版 46幅全彩插图！）', '安托万·德·圣-埃克苏佩里', '天津人民出版社', '9787201077642', 121, 'D区19排5架', 41.48, '2017-02-01', '/api/uploads/covers/112269.jpg', '小王子是一个超凡脱俗的仙童，他住在一颗只比他大一丁点儿的小行星上。陪伴他的是一朵他非常喜爱的小玫瑰花。但玫瑰花的虚荣心伤害了小王子对她的感情。小王子告别小行星，开始了遨游太空的旅行。他先后访问了六个行星，各种见闻使他陷入忧伤，他感到大人们荒唐可笑、太不正常。只有在其中一个点灯人的星球上，小王子才找到一个可以作为朋友的人。但点灯人的天地又十分狭小，除了点灯人他自己，不能容下第二个人。在地理学家的指点下，孤单的小王子来到人类居住的地球。 小王子发现人类缺乏想象力，只知像鹦鹉那样重复别人讲过的话。小王子这时越来越思念自己星球上的那枝小玫瑰。后来，小王子遇到一只小狐狸，小王子用耐心征服了小狐狸，与它结成了亲密的朋友。小狐狸把自己心中的秘密——肉眼看不见事务的本质，只有用心灵才能洞察一切——作为礼物，送给小王子。用这个秘密，小王子在撒哈拉大沙漠与遇险的飞行员一起找到了生命的泉水。最后，小王子在蛇的帮助下离开地球，重新回到他的B612号小行星上。 童话描写小王子没有被成人那骗人的世界所征服，而最终找到自己的理想。这理想就是连结宇宙万物的爱，而这种爱又是世间所缺少的。因此，小王子常常流露出一种伤…', 8, 8, 1, '2026-09-09 19:07:07'),
  ('【精品汇】百年孤独', '加西亚·马尔克斯', '南海出版公司', '9000000133347', 121, 'B区15排10架', 97.69, '2017-08', '/api/uploads/covers/133347.jpg', '《百年孤独》是加西亚·马尔克斯的代表作，也是拉丁美洲魔幻现实主义文学的代表作。小说通过布恩迪亚家族七代人的兴衰史，描绘了马孔多小镇的百年兴衰，展现了拉丁美洲的历史和社会变迁。 小说以其独特的叙事风格和丰富的想象力，吸引了无数读者。作者通过魔幻现实主义的手法，将现实与幻想、历史与神话巧妙地结合在一起，创造出一个充满魔幻色彩的世界。', 8, 8, 1, '2026-09-09 19:07:07'),
  ('肖申克的救赎（斯蒂芬·金为人津津乐道的杰出代表作，不朽的励志经典，同名电影被誉为电影史上完美影片之一） (斯蒂芬·金作品系列)', '斯蒂芬·金', '', '9000000224553', 121, 'C区16排12架', 84.5, '2018-09', '/api/uploads/covers/224553.jpg', '《肖申克的救赎》是斯蒂芬·金为人津津乐道的杰出代表作，被誉为不朽的励志经典。小说讲述了银行家安迪·杜佛兰因被冤枉杀害妻子及其情人而被判无期徒刑，关押在肖申克监狱。在监狱中，安迪凭借自己的智慧和毅力，不仅赢得了狱友的尊重，还最终实现了自我救赎。 同名电影被誉为电影史上完美影片之一，深受观众喜爱。小说通过细腻的笔触和深刻的内涵，探讨了人性、希望和自由的主题，给读者带来了深刻的思考和感动。', 4, 4, 1, '2026-09-09 19:07:07'),
  ('杀死一只知更鸟 (哈珀·李作品)', '哈珀·李', '译林出版社', '9787544766500', 121, 'C区4排11架', 61.89, '2017-02-01', '/api/uploads/covers/99279.jpg', '这本书被誉为（“塑造美国的88部图书”之一，普利策奖、奥斯卡金像奖获奖作品、影响全球5000万家庭的教养圣经，奥巴马、贝克汉姆、奥普拉鼎力推荐） (哈珀·李作品) 《杀死一只知更鸟》是公认的美国文学经典,而它在教育领域的意义却使其突破了国界,成为世界上最有名的成长小说之一。《杀死一只知更鸟》在西方世界的影响力巨大,是美国中小学的必读书目,图书馆借阅次数最高的图书,以及英国青少年最喜爱的图书,在最近一次民意投票中,它甚至压倒《圣经》,成为“最具启示意义的书”。 《杀死一只知更鸟》的可贵之处在于,它塑造了人类家庭教育的典范,并提供了极具可操作性的实例与示范。和很多要去保持儿童纯净心灵的虚构故事不同,它着力教导孩子如何在磨难中历练风度,在不公平中积累正气,如何在充满丑陋与问题的世界中塑造自己的道德底线,保持精神的体面。除此之外,书中的阿迪克斯这位平民英雄父亲为迷茫的父母提供了一本教育说明书:如何去鉴别孩子的问题,那些是年龄造成的,应该给他们时间去成长,哪些问题又是成长中的关键,是原则问题,必须及时干预;父母应该是什么样一个形象,在复杂的社会中,哪些方面应该去适应去顺应,哪些方面应该坚持自…', 5, 5, 1, '2026-09-09 19:07:07'),
  ('1984（插图珍藏版·慢读系列）【世界文坛反乌托邦经典、美国时代杂志百佳英文小说】', '乔治·奥威尔', '群言出版社', '9787530210291', 121, 'A区5排1架', 39.52, '2016-04-25', '/api/uploads/covers/26008.jpg', '★村上春树以《1Q84》向本书致敬 ★著名学者刘绍铭经典译本内地首次出版 ★62种文字风靡110个国家,全球销量超过5000万册 ★《时代周刊》“最好的100本英语小说” ★兰登书屋“100本20世纪最佳英语小说” ★入选英美中学生必读书书目 1936年以来,我所写的每 一部严肃作品,都是直接或间接地反对极权主义,支持我所理解的民主社会主义。——乔治•奥威尔(《我为何写作》) 《1984》是一部杰出的政治寓言小说,也是一部幻想小说。作品刻画了人类在极权主义社会的生存状态,有若一个永不褪色的警示标签,警醒世人提防这种预想中的黑暗成为现实。历经几十年,其生命力益显强大,被誉为20世纪影响最为深远的文学经典之一。', 6, 6, 1, '2026-09-09 19:07:07'),
  ('白鹿原（茅盾文学奖获奖作品；插图珍藏精装本）', '陈忠实著', '人民文学出版社', '9000000142914', 113, 'A区19排8架', 78.69, '2012-09', '/api/uploads/covers/142914.jpg', '在从清末民初到建国之初的半个世纪里，一阵阵狂风掠过了白鹿原上空，而每一次的变动都震荡着它的内在结构：打乱了再恢复，恢复了再打乱，细腻地反映出白姓和鹿姓两大家族祖孙三代的恩怨纷争。陈忠实先生在这里，人物的命运是纵线，百回千转，社会历史的演进是横面，愈拓愈宽，传统文化的兴衰则是全书的精神主体，以至人、社会历史、文化精神三者之间相互激荡，相互作用，共同推进了作品的时空，在我们眼前铺开了一轴恢宏的、动态的、极富纵深感的关于我们民族灵魂的现实主义的画卷。 新版《白鹿原》特色： 1、完整呈现了1993年最原始版本。 2、全新精装本。内附多幅彩插，包括作者旧照、手稿影印件。更有电影《白鹿原》的美术设计师创作的精美插图首次面世。 3、全书浓缩着深沉的民族历史内涵，有令人震撼的真实感和厚重的史诗风格。 4、本书1997年荣获中国长篇小说最高荣誉–第四届茅盾文学奖。已被改编成同名话剧、电影、舞剧、秦腔等多种艺术形式。', 8, 8, 1, '2026-09-09 19:07:07'),
  ('活着 (余华作品)', '余华', '作家出版社', '9787530215593', 113, 'A区3排12架', 40.55, '2008-05-01', '/api/uploads/covers/124404.jpg', '【内容简介】 《活着》是当代作家余华的代表作,讲述了一个人历尽世间沧桑和磨难的一生,亦将中国大半个世纪的社会变迁凝缩其间。《活着》还讲述了眼泪的宽广和丰富;讲述了绝望的不存在;讲述了人是为了活着本身而活着的,而不是为了活着之外的任何事物而活着。 《活着》出版25年来打动了无数读者,经过时间的沉淀,已成为20世纪中国文学当之无愧的经典之作。到今天,已被译介至英、法、德、意、日、韩、俄等30多个国家和地区,获得国内外多个文学大奖,余华也凭借这部作品于2004年获得法兰西艺术和骑士文化勋章。 25年后重新修订出版,相信《活着》仍然会以超越时间与空间的精神内核,击中我们每个人的心。 【获奖情况】 意大利格林扎纳·卡佛文学奖最高奖项 台湾“中国时报”十大好书奖 《亚洲周刊》二十世纪中文小说一百强 【媒体推荐】 中国过去六十年所发生的一切灾难,都一一发生在福贵和他的家庭身上。接踵而至的打击或许令读者无从同情,但余华至真至诚的笔墨,已将福贵塑造成了一个存在的英雄。当这部沉重的小说结束时,活着的意志,是福贵身上不能被剥夺走的东西。——美国《时代》周刊 余华的作品可以比得上卡夫卡和博尔赫斯的作品的风…', 6, 6, 1, '2026-09-09 19:07:07'),
  ('《全球神祇之我的信徒有点苟》作者：绿笔', '绿笔', '', '9000000018007', 113, 'D区3排8架', 77.65, NULL, '/api/uploads/covers/18007.jpg', '内容简介：神祇时代，人人皆为神明，体内创立神国，高举神火，万族繁衍。就在神明们还在争论到底是半兽人厉害，还是亡灵系大军恐怖的时候。林凡看着自己的十万个钻在草丛里', 2, 2, 1, '2026-09-09 19:07:07'),
  ('《赤色黎明》作者：绯红之月', '绯红之月', '', '9000000001114', 113, 'C区6排11架', 82.74, NULL, '/api/uploads/covers/1114.jpg', '1905年，黎明前的黑暗，魑魅魍魉、百鬼夜行。前方有无数的岔道，前方也只有唯一的生路。砸碎奴役者们所铸造的一切枷锁，我们在革命中失去的只有锁链，获得的则是整个世', 7, 7, 1, '2026-09-09 19:07:07'),
  ('卡拉马佐夫兄弟（套装上下册） (陀思妥耶夫斯基文集)', '陀思妥耶夫斯基(Fyodor Dostoyevsky)', '上海译文出版社', '9787532763696', 121, 'C区8排5架', 53.15, '2017-04', '/api/uploads/covers/187557.jpg', '《卡拉马佐夫兄弟》是俄国作家陀思妥耶夫斯基的代表作之一，小说通过卡拉马佐夫家族的故事，深刻探讨了人性、信仰、道德与罪恶等主题。 小说围绕老卡拉马佐夫和他的三个儿子展开，每个角色都有鲜明的个性和复杂的内心世界，展现了人性的多面性和深度。 陀思妥耶夫斯基以其独特的叙事手法和深刻的心理描写，使这部作品成为世界文学史上的经典之作。', 6, 6, 1, '2026-09-09 19:07:07'),
  ('东野圭吾：白夜行 (新经典文库•东野圭吾作品)', '东野圭吾 (Higashino Keigo)', '南海出版公司', '9787544291163', 122, 'D区4排9架', 77.05, '2012-01-01', '/api/uploads/covers/96762.jpg', '《白夜行》被普遍视为日本作家东野圭吾作品的无冕之王,一经推出即成为东野圭吾的长篇小说代表作,中文版销量超450万册,与《嫌疑人X的献身》《恶意》《解忧杂货店》并称为东野圭吾四大杰作。 《白夜行》是东野圭吾当之无愧的鸿篇巨制,全书故事跨越19年时间,登场人物超过50个,草蛇灰线伏脉千里,情节线索纵横交错又丝丝入扣,用一桩离奇命案牵出案件相关人跨越19年惊心动魄的故事、悲凉的爱情、吊诡的命运、令人发指的犯罪、白描又生动的社会图景、复杂人性的对决与救赎,读来令人叹为观止。 1973年,大阪一栋废弃建筑中发现一名遭利器刺死的男子。警方怀疑一个叫西本文代的女人,但缺少证据。不久西本被判定因意外事故死亡,从此案件成谜。此后19年,众多案件相关者的命运出现了离奇的转折,有人走向上流社会,有人在暗夜中游走挣扎。只有一个老警察追查不休,渐渐拼出了惊人的真相。', 7, 7, 1, '2026-09-09 19:07:07'),
  ('《死亡阶梯》作者：大袖遮天', '大袖遮天', '', '9000000017803', 113, 'B区13排10架', 77.2, NULL, '/api/uploads/covers/17803.jpg', '内容简介一个村庄的诅咒，接二连三的“意外”死亡，一个缜密复杂的谋杀模式，一场规模浩大的人体试验……一个年轻女子杨小惠被害，凶手很快被抓捕归案，但是案件背后却隐藏', 2, 2, 1, '2026-09-09 19:07:07'),
  ('《诡秘地海》作者：狐尾的笔', '狐尾的笔', '', '9000000002172', 113, 'D区20排7架', 77.9, NULL, '/api/uploads/covers/2172.jpg', '内容简介：漆黑诡秘的地下海泽，神秘的岛屿惊悚的畸形怪物，人类不是这鬼地方的主角，疯癫与死亡才是。对那些海底东西的卑微祈求，只会让可怜虫们在黑暗苟延残喘逐渐畸形，', 3, 3, 1, '2026-09-09 19:07:07'),
  ('《从十倍到十万亿倍无限升级系统》作者：小猪快写', '小猪快写', '', '9000000017921', 121, 'C区9排8架', 12.45, NULL, '/api/uploads/covers/17921.jpg', '内容简介：“恭喜宿主，获得天阶低级功法一部。”“领取X10”“要想身体好，天天吃烧烤！”白飘懵逼的看着眼前的广告，半天没有回过神。我特么领个十倍奖励，还有15秒', 5, 5, 1, '2026-09-09 19:07:07'),
  ('《诡域档案》作者：墨绿青苔', '墨绿青苔', '', '9000000008180', 113, 'C区8排3架', 66.18, NULL, '/api/uploads/covers/8180.jpg', '内容简介：六年前华夏国国家安全部优秀的侦察员、七局的副局长彭刚同志在执行任务的过程中离奇遇害，当时和他在一起的同志亲眼见到他就像是被人勒住了脖子一般，双手挥舞着', 3, 3, 1, '2026-09-09 19:07:07'),
  ('《山村禁地：我教孩子抓鬼被曝光了》作者：疯何子', '疯何子', '', '9000000015997', 113, 'B区18排2架', 56.03, NULL, '/api/uploads/covers/15997.jpg', '内容简介：【已有完本作品，质量保证】吴念觉醒阴曹地府系统，在一处偏僻的山村支教，培养属于自己的鬼差。本来想着教孩子捉捉鬼，熟悉下业务，将来也能让他们边捉鬼边挣钱', 5, 5, 1, '2026-09-09 19:07:07'),
  ('围城（爱熄灭了灯，心围一座城。出版七十周年纪念版）', '钱钟书', '人民文学出版社', '9787020090006', 113, 'C区9排7架', 38.8, '2017-07-01', '/api/uploads/covers/72208.jpg', '《围城》是一幅栩栩如生的世井百态图,人生的酸甜苦辣千般滋味均在其中得到了淋漓尽致的体现。钱钟书先生将自己的语言天才并入极其渊博的知识,再添加上一些讽刺主义的幽默调料,以一书而定江山。《围城》显示给我们一个真正的聪明人是怎样看人生,又怎样用所有作家都必得使用的文字来表述自己的“观”和“感”的。', 6, 6, 1, '2026-09-09 19:07:07'),
  ('追风筝的人——卡勒德·胡赛尼', '[美]卡勒德·胡赛尼', '上海人民出版社', '9787208061644', 121, 'C区20排11架', 29.56, '2016-03-30', '/api/uploads/covers/112789.jpg', '12岁的阿富汗富家少爷阿米尔与仆人哈桑情同手足。然而,在一场风筝比赛后,发生了一件悲惨不堪的事,阿米尔为自己的懦弱感到自责和痛苦,逼走了哈桑,不久,自己也跟随父亲逃往美国。 成年后的阿米尔始终无法原谅自己当年对哈桑的背叛。为了赎罪,阿米尔再度踏上暌违二十多年的故乡,希望能为不幸的好友尽最后一点心力,却发现一个惊天谎言,儿时的噩梦再度重演,阿米尔该如何抉择? 故事如此残忍而又美丽,作者以温暖细腻的笔法勾勒人性的本质与救赎,读来令人荡气回肠。', 5, 5, 1, '2026-09-09 19:07:07'),
